const $=(selector,root=document)=>root.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(value,d=0)=>value==null||!Number.isFinite(Number(value))?'—':Number(value).toLocaleString('en-US',{maximumFractionDigits:d});
const date=value=>{const d=new Date(value);return value&&!Number.isNaN(d.valueOf())?d.toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'Not available';};
const pretty=value=>String(value??'').replace(/_/g,' ').replace(/^./,c=>c.toUpperCase());
const icon=name=>`<span class="icon" aria-hidden="true">${icons[name]||icons['circle-help']||''}</span>`;
const brand=()=>'<a class="brand" href="/" data-nav><img src="/assets/aeroguard.svg" alt=""><span>AeroGuard</span></a>';
const button=(label,action,ico='',type='',extra='')=>`<button type="button" class="button ${type}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const link=(label,path,ico='',type='',extra='')=>`<a class="button ${type}" href="${path}" data-nav ${extra}>${ico?icon(ico):''}${label}</a>`;
const badge=(label,style=label)=>`<span class="badge ${esc(String(style).toLowerCase())}">${esc(pretty(label))}</span>`;
const tag=(subset)=>`<span class="tag">${esc(subset)}</span>`;
const empty=(title,copy,action='',ico='database')=>`<div class="empty"><div class="empty-icon">${icon(ico)}</div><h3>${title}</h3><p>${copy}</p>${action}</div>`;
const notice=(title,copy,type='')=>`<div class="notice ${type}">${icon(type==='warning'?'triangle-alert':'shield-check')}<div><strong>${title}</strong>${copy}</div></div>`;
const heading=(title,copy,actions='')=>`<header class="page-header"><div><h1>${title}</h1><p>${copy}</p></div><div class="actions">${actions}</div></header>`;
const panel=(title,content,subtitle='',action='',cls='')=>`<section class="panel ${cls}"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div>${action}</div><div class="panel-body">${content}</div></section>`;
const subsets=['FD001','FD002','FD003','FD004'];
const routeInfo={dashboard:['Fleet Overview','layout-dashboard'],engines:['Engine Explorer','wind'],analytics:['Analytics','chart-no-axes-combined'],models:['Model Registry','boxes'],'work-orders':['Work Orders','clipboard-list'],pipeline:['Data Pipeline','network'],data:['Dataset Management','database'],settings:['Settings','settings']};
const defaults={workspace_name:'AeroGuard Research',researcher_name:'Local researcher',default_subset:'ALL',policy:{critical_rul:5,critical_lower:10,critical_upper:10,attention_lower:30,watch_lower:50,anomaly_attention:.99,anomaly_extreme:.995,trend_threshold:.04,persistence:3,critical_persistence:2,rearm_cycles:5},promotion_rmse_tolerance_percent:0,promotion_nasa_tolerance_percent:5,replay_cycles:30,uncertainty_gate:80};
const state={mode:localStorage.getItem('aeroguard-mode')==='demo'?'demo':'benchmark',subset:localStorage.getItem('aeroguard-subset')||'ALL',route:'/',data:null,settings:null,health:null,engineSearch:'',severity:'ALL',cycleMin:'',cycleMax:'',enginePage:0,orderSearch:'',orderStatus:'all',orderPriority:'ALL',orderPage:0,detailTab:'overview',detailLimit:60,selectedSensor:'',previewSubset:'FD001',previewPartition:'train',comparison:new Set(),jobId:null,trendAsset:null,generation:0,jobKeys:new Map(),busy:new Set(),pendingConfirm:null};
if(![...subsets,'ALL'].includes(state.subset))state.subset='ALL';
const modeQuery=()=>`mode=${state.mode}`;
const filters=()=>new URLSearchParams({mode:state.mode,subset:state.subset,...(state.engineSearch?{engine:state.engineSearch}:{}),...(state.severity!=='ALL'?{severity:state.severity}:{}),...(state.cycleMin?{cycle_min:state.cycleMin}:{}),...(state.cycleMax?{cycle_max:state.cycleMax}:{})}).toString();
const enginePath=asset=>'/engines/'+encodeURIComponent(asset);
const engineLabel=a=>`${a.subset}-${String(a.engine_id).padStart(3,'0')}`;
const health=a=>a.health||({NORMAL:'healthy',CRITICAL:'critical',NOT_REPLAYED:'unknown',WARMING_UP:'unknown'}[a.state]||'attention');

async function api(path,{method='GET',body,job=false,key,signal}={}){
  const headers={};if(method!=='GET')headers['X-AeroGuard-Client']='dashboard';
  if(body!==undefined&&!(body instanceof FormData))headers['Content-Type']='application/json';
  if(job)headers['Idempotency-Key']=key||crypto.randomUUID();
  const response=await fetch('/api'+path,{method,headers,body:body===undefined?undefined:body instanceof FormData?body:JSON.stringify(body),signal});
  let data;try{data=await response.json();}catch{throw new Error(`The service returned an unreadable response (${response.status}).`);}
  if(!response.ok){const message=data.error?.message||data.error||data.detail?.map?.(e=>`${e.loc?.slice(1).join('.')}: ${e.msg}`).join('\n')||data.detail||`Request failed (${response.status})`;throw new Error(typeof message==='string'?message:JSON.stringify(message));}
  return data;
}
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,6500);}
function navigate(path,{replace=false}={}){document.querySelectorAll('dialog[open]').forEach(d=>d.close());replace?history.replaceState({},'',path):history.pushState({},'',path);state.enginePage=0;state.orderPage=0;render();scrollTo(0,0);}
function selectedSubsets(){return state.subset==='ALL'?subsets:[state.subset];}
function subsetSelect(id='global-subset'){return `<label class="sr-only" for="${id}">Dataset subset</label><select class="select" id="${id}"><option value="ALL">All datasets</option>${subsets.map(s=>`<option ${state.subset===s?'selected':''}>${s}</option>`).join('')}</select>`;}
function metricCards(items){return `<div class="metric-grid">${items.map(([label,value,foot,ico,tint])=>`<article class="metric-card"><span class="metric-icon ${tint||''}">${icon(ico)}</span><div><p class="metric-label">${label}</p><div class="metric-value">${value}</div><div class="metric-foot ${tint==='green'?'positive':''}">${foot}</div></div></article>`).join('')}</div>`;}
function shell(){
  const active=state.route.split('/')[1],profile=state.settings?.researcher_name||'Local researcher';
  const researchView=active==='models'&&new URLSearchParams(location.search).has('research');
  return `<aside class="sidebar" id="sidebar" aria-label="Application navigation">${brand()}<div class="workspace-chip"><span class="workspace-icon">${icon('layers')}</span><div>${esc(state.settings?.workspace_name||'Research workspace')}<small>Local · NASA C-MAPSS</small></div></div><div class="mobile-context"><label class="field-label" for="mobile-subset">Dataset subset</label><select class="select" id="mobile-subset"><option value="ALL">All datasets</option>${subsets.map(s=>`<option ${state.subset===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="nav-label">WORKSPACE</div><nav>${Object.entries(routeInfo).map(([path,[title,ico]])=>`<a class="nav-item ${active===path?'active':''}" href="/${path}" data-nav ${active===path?'aria-current="page"':''}>${icon(ico)}<span>${title}</span></a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('shield-check')}<strong>From prediction to prevention.</strong><p>Trace every decision from sensor history to a maintenance outcome.</p><a href="/downloads/notebook">CUDA research notebook ${icon('arrow-up-right')}</a></div><a class="profile-link" href="/settings" data-nav><span class="avatar">${esc(profile[0].toUpperCase())}</span><span>${esc(profile)}<small>Local workspace settings</small></span>${icon('settings')}</a></div></aside><div class="shell"><header class="topbar"><button class="icon-button mobile-nav" data-action="menu" aria-expanded="false" aria-label="Toggle navigation">${icon('menu')}</button><div class="top-search"><form id="global-search-form">${icon('search')}<label class="sr-only" for="global-search">Search engines and work orders</label><input id="global-search" placeholder="Search engine, work order…" autocomplete="off"></form><div class="popover search-popover" id="search-results" hidden></div></div><div class="topbar-actions">${researchView?tag(state.data?.subset||'Research'):state.route==='/settings'?'':subsetSelect()}${researchView?'<span class="source-pill">GPU research export</span>':`<label class="sr-only" for="data-mode">Data mode</label><select id="data-mode" class="mode-select ${state.mode==='demo'?'demo':''}"><option value="benchmark" ${state.mode==='benchmark'?'selected':''}>Benchmark data</option><option value="demo" ${state.mode==='demo'?'selected':''}>Demo examples</option></select>`}<div class="notification-wrap"><button class="icon-button" data-action="notifications" aria-label="Notifications" aria-expanded="false">${icon('bell')}</button><div id="notifications" class="popover" hidden></div></div><a class="avatar top-avatar" href="/settings" data-nav aria-label="User settings">${esc(profile[0].toUpperCase())}</a></div></header><div class="mode-strip ${!researchView&&state.mode==='demo'?'demo':''}">${icon(researchView?'brain-circuit':state.mode==='demo'?'flask-conical':'clock')}${researchView?'<strong>GPU research export</strong> · Historical engine results; explanation provenance is recorded below.':state.mode==='demo'?'<strong>Demonstration data</strong> · Synthetic engine histories and simulated work orders. <button data-action="benchmark-mode">Use benchmark data</button>':'Historical NASA C-MAPSS benchmark replay · CPU baseline results · Not a live physical sensor stream.'}</div><main id="main" class="workspace-main" tabindex="-1"></main><footer class="app-footer"><span>AeroGuard · Predictive Maintenance Intelligence</span><span>NASA C-MAPSS · Traceable decisions · Local workspace</span></footer></div>`;
}
function landingMarkup(data){
  const asset=data?.assets?.[0],datasetInfo=[['21','Sensors per engine','activity'],['4','C-MAPSS subsets','boxes'],['Historical','Cycle replay','clock'],['Traceable','Work orders','wrench'],['Reproducible','Model training','brain-circuit']];
  const stages=[['database','Data ingestion','Validate original NASA files or uploaded sensor batches.','/data'],['settings','Feature preparation','Clean inputs and build causal rolling-window features.','/data'],['brain-circuit','Model inference','Independent anomaly detection and RUL prediction.','/models'],['network','Rule-based triage','Apply quality gates, thresholds, and persistence checks.','/pipeline'],['wrench','Maintenance orders','Create deduplicated records and capture outcomes.','/work-orders'],['chart-no-axes-combined','Monitor & retrain','Compare measured runs and guard model promotion.','/analytics']];
  return `<div class="landing"><header class="landing-header">${brand()}<nav class="landing-nav" aria-label="Product navigation"><a href="/" data-nav>Home</a><a href="/dashboard" data-nav>Dashboard</a><a href="/pipeline" data-nav>Solution</a><a href="/models" data-nav>Technology</a><a href="/data" data-nav>Dataset</a></nav><div class="actions">${link('Get started','/dashboard','','primary')}</div></header><main id="main"><section class="landing-hero"><div class="landing-image" aria-hidden="true"></div><div class="landing-shade" aria-hidden="true"></div><div class="hero-copy"><p class="eyebrow">PREDICT · PREVENT · KEEP FLEETS MOVING</p><h1>Self-Healing <span>Machines</span> for a Safer Tomorrow.</h1><p>Predictive maintenance for connected fleets. Turn sensor histories into reliable insights, remaining-life estimates, and traceable maintenance decisions.</p><div class="actions">${link('Explore Dashboard','/dashboard','arrow-right','primary')}${link('View Pipeline','/pipeline','network')}</div><div class="hero-small">${icon('shield-check')}Built for the Tata Elxsi TELEIPORT case study</div></div><aside class="hero-result"><p class="eyebrow">${asset?(state.mode==='demo'?'SYNTHETIC DEMONSTRATION':'CPU BASELINE · MEASURED'):'MODEL-BACKED INTELLIGENCE'}</p><h3>${asset?'Engine '+engineLabel(asset):'Your fleet, in focus'}</h3>${asset?`<strong>${num(asset.rul)} <span>cycles</span></strong><p>Predicted remaining useful life · ${esc(asset.subset)}</p>${badge(health(asset))}`:'<strong>Predict. <span>Prepare.</span></strong><p>Connect a trained model to inspect actual engine predictions and decisions.</p>'+link('Open workspace','/models','arrow-right','small soft')}</aside></section><div class="capability-bar">${datasetInfo.map(([n,label,ico])=>`<div class="capability">${icon(ico)}<div><strong>${n}</strong>${label}</div></div>`).join('')}</div><section class="landing-section"><div class="section-heading"><div><p class="eyebrow">THE CONNECTED WORKFLOW</p><h2>From engine data to the next right action.</h2><p>A complete, inspectable pipeline connects machine learning with ordinary Python rules and a persistent maintenance workflow.</p></div>${link('Explore the pipeline','/pipeline','arrow-right','soft')}</div><div class="solution-flow">${stages.map(([ico,title,copy,path],i)=>`<article class="solution-step">${icon(ico)}<h3>${i+1}. ${title}</h3><p>${copy}</p><a href="${path}" data-nav>Explore ${icon('arrow-right')}</a></article>`).join('')}</div></section><section class="landing-section"><div class="landing-data"><div><p class="eyebrow">REAL BENCHMARK. HONEST RESULTS.</p><h2>Engineering insight starts with the right evidence.</h2><p>NASA C-MAPSS simulates turbofan degradation across four operating and fault-condition subsets. AeroGuard replays historical engine cycles and processes uploaded batches. It never presents this benchmark as a live physical sensor feed.</p><div class="dataset-pills">${subsets.map(s=>`<a class="dataset-pill" href="/data?subset=${s}" data-nav>${s}</a>`).join('')}</div><div class="actions">${link('Explore the data','/data','database','soft')}<a class="text-button" href="https://data.nasa.gov/dataset/cmapss-jet-engine-simulated-data" target="_blank" rel="noopener">NASA dataset ${icon('arrow-up-right')}</a></div></div><div class="landing-data-card"><h3>Built for reproducible experiments</h3><div class="key-values"><div><span>Sensor measurements</span><strong>21 per operational cycle</strong></div><div><span>Operating settings</span><strong>3 recorded settings</strong></div><div><span>Prediction target</span><strong>Remaining useful life · cycles</strong></div><div><span>Evaluation</span><strong>Original held-out test engines</strong></div><div><span>Triage agent</span><strong>Python rules · no LLM</strong></div><div><span>Work-order delivery</span><strong>Simulated local records</strong></div></div></div></div></section><section class="landing-section"><div class="section-heading"><div><p class="eyebrow">THE IMPLEMENTED STACK</p><h2>Practical by design. Transparent at every layer.</h2><p>Purpose-built components keep preprocessing, prediction, triage, and persistence independently understandable.</p></div><a class="button" href="/documents/system.svg" target="_blank" rel="noopener">${icon('network')}Architecture diagram</a></div><div class="tech-grid">${[['cpu','Python + FastAPI','Validated APIs and persistent background pipeline jobs.'],['brain-circuit','scikit-learn','A real RUL baseline and independent anomaly model.'],['database','SQLite','Durable events, work orders, settings, and audit history.'],['chart-no-axes-combined','MLflow','Parameters, artifacts, and measured experiment results.'],['layers','Transformer–KAN–BiLSTM','Selected GPU research architecture, condition-gate ablation, and final SHAP/LIME analysis.']].map(([ico,title,copy])=>`<article class="tech-item">${icon(ico)}<strong>${title}</strong><p>${copy}</p></article>`).join('')}</div></section><section class="landing-cta"><div><h2>See the whole fleet. Understand every decision.</h2><p>Explore benchmark results or use clearly labelled demonstration examples.</p></div><div class="actions">${link('Explore Dashboard','/dashboard','arrow-right','primary')}${button('Try demonstration','landing-demo','flask-conical')}</div></section></main><footer class="landing-footer">${brand()}<span>Historical benchmark replay · Simulated maintenance records</span><div class="landing-footer-links"><a href="/data" data-nav>Dataset</a><a href="/models" data-nav>Models</a><a href="/downloads/notebook">Training notebook</a></div></footer></div>`;
}

function filterBar(){return `<form id="filters-form" class="filter-row"><div class="field"><label for="engine-filter">Engine ID</label><input id="engine-filter" name="engine" value="${esc(state.engineSearch)}" placeholder="e.g. FD001 or 003"></div><div class="field"><label for="severity-filter">Health status</label><select id="severity-filter" name="severity"><option value="ALL">All statuses</option>${['healthy','attention','critical','unknown'].map(s=>`<option value="${s}" ${state.severity===s?'selected':''}>${pretty(s)}</option>`).join('')}</select></div><div class="field small-field"><label for="cycle-min">From cycle</label><input id="cycle-min" type="number" min="0" name="cycle_min" value="${esc(state.cycleMin)}" placeholder="Any"></div><div class="field small-field"><label for="cycle-max">To cycle</label><input id="cycle-max" type="number" min="0" name="cycle_max" value="${esc(state.cycleMax)}" placeholder="Any"></div><button class="button small" type="submit">${icon('filter')}Apply filters</button>${button('Reset','reset-filters','rotate-ccw','small')}</form>`;}
function engineRows(assets){return assets.map(a=>`<tr data-engine="${esc(a.asset)}" tabindex="0" aria-label="View engine ${esc(engineLabel(a))}"><td><div class="engine-cell">${icon('wind')}<div><strong>${engineLabel(a)}</strong><small>${state.mode==='demo'?'SYNTHETIC EXAMPLE':a.partition==='incoming'?'UPLOADED BATCH':'TEST REPLAY'} · ${esc(a.asset)}</small></div></div></td><td>${tag(a.subset)}</td><td>${num(a.cycle)}</td><td><span class="inline-meter"><span class="rul-value">${num(a.rul,1)}</span><span class="meter"><i style="width:${Math.min(100,Math.max(0,a.rul/125*100))}%;background:${colors[health(a)]||colors.blue}"></i></span></span></td><td>${a.anomaly==null?'Unavailable':num(a.anomaly*100,1)+'%'}</td><td>${badge(health(a))}</td><td>${num((a.quality??0)*100)}%</td><td><span class="icon" style="width:13px;color:#9CB0C9">${icons['chevron-right']}</span></td></tr>`).join('');}
function engineTable(assets,{compact=false}={}){
  const total=assets.length,size=compact?6:20,page=compact?0:Math.min(state.enginePage,Math.max(0,Math.ceil(total/size)-1)),shown=assets.slice(page*size,(page+1)*size),hasFilters=Boolean(state.engineSearch||state.severity!=='ALL'||state.cycleMin||state.cycleMax);
  return `<section class="panel"><div class="table-toolbar"><h2>${compact?'Engine watchlist':'All engines'}</h2>${compact?'<a class="text-button" href="/engines" data-nav>View all engines '+icon('arrow-right')+'</a>':`<span class="source-pill">${state.mode==='demo'?'SYNTHETIC EXAMPLES':'FROZEN MODEL RESULTS'}</span>`}</div><div class="table-scroll"><table><thead><tr><th>ENGINE</th><th>DATASET</th><th>CURRENT CYCLE</th><th>PREDICTED RUL</th><th>ANOMALY PERCENTILE</th><th>HEALTH STATUS</th><th>TRUSTED DATA</th><th></th></tr></thead><tbody>${shown.length?engineRows(shown):`<tr><td colspan="8">${empty(hasFilters?'No matching engines':'No model-backed engines yet',hasFilters?'No engines match the current ID, status, and cycle filters. Reset or adjust the filters to see recorded engines.':'Train and evaluate a model for this subset, or select Demo examples in the top bar.',hasFilters?button('Reset filters','reset-filters','rotate-ccw','small soft'):link('Open model registry','/models','boxes','small soft'),'wind')}</td></tr>`}</tbody></table></div><div class="table-pagination"><span>Showing ${total?page*size+1:0}–${Math.min(total,(page+1)*size)} of ${total} engines</span>${!compact?`<div class="actions">${button('Previous','engine-prev','chevron-right','small',page===0?'disabled':'')}${button('Next','engine-next','arrow-right','small',(page+1)*size>=total?'disabled':'')}</div>`:'<span>Remaining life is measured in cycles</span>'}</div></section>`;
}
function recentOrders(orders,limit=5){const chosen=orders.slice(0,limit);return chosen.length?`<div class="table-scroll"><table><thead><tr><th>ORDER</th><th>ENGINE</th><th>PRIORITY</th><th>STATUS</th><th></th></tr></thead><tbody>${chosen.map(o=>`<tr><td><button class="text-button" data-action="order-detail" data-id="${esc(o.id)}">${esc(o.id)}</button></td><td>${esc(o.asset)}</td><td>${badge(o.priority)}</td><td>${badge(o.status)}</td><td><button class="text-button" data-action="order-detail" data-id="${esc(o.id)}">View ${icon('arrow-up-right')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('No work orders yet','Persistent triage conditions create simulated maintenance records here.','','wrench');}
function recentAlerts(assets){const attention=assets.filter(a=>['attention','critical'].includes(health(a))).sort((a,b)=>(health(a)==='critical'?0:1)-(health(b)==='critical'?0:1)).slice(0,5);return attention.length?`<div class="table-scroll"><table><thead><tr><th>ENGINE</th><th>CYCLE</th><th>SEVERITY</th><th>OBSERVATION</th><th>PREDICTED RUL</th></tr></thead><tbody>${attention.map(a=>`<tr><td><a class="text-button" href="${enginePath(a.asset)}" data-nav>${engineLabel(a)}</a></td><td>${num(a.cycle)}</td><td>${badge(health(a))}</td><td>${esc(a.decision?.reason||a.quality_reason||pretty(a.state))}</td><td>${num(a.rul,1)} cycles</td></tr>`).join('')}</tbody></table></div>`:empty('No current alerts','No attention or critical conditions appear in this filtered view.','','shield-check');}
function dashboardPage(data){
  const s=data.summary,assets=data.assets||[],total=Number(s.total||0),percent=v=>total?`${num(v/total*100)}% of processed engines`:'Awaiting processed engines',latest=data.jobs?.[0];
  return heading('Fleet Overview','Engine health monitoring and predictive maintenance insights.',`${button('Run pipeline','pipeline-dialog','play','primary')}${link('Explore engines','/engines','arrow-right')}`)+metricCards([
    ['Total Engines',num(total),`${num(s.models_active||0)} active subset models`,'boxes',''],['Healthy',num(s.healthy||0),percent(s.healthy||0),'heart-pulse','green'],['Attention',num(s.attention||0),percent(s.attention||0),'triangle-alert','orange'],['Critical',num(s.critical||0),percent(s.critical||0),'circle-alert','red']
  ])+(s.unknown?notice(`${num(s.unknown)} engines await a supported decision`,'Unreplayed histories, short contexts, or unavailable evidence remain explicitly labelled rather than counted as healthy.'):state.mode==='benchmark'&&!total?notice('Connect a trained model to your fleet.','Import the four NASA subsets, train a baseline, and inspect actual results. Demo examples remain available separately.'):'' )+filterBar()+`<div class="panel-grid">${panel('RUL Distribution',`<div class="chart-legend"><span><i style="background:#16A784"></i>Healthy</span><span><i style="background:#EAA33B"></i>Attention</span><span><i style="background:#E45C5C"></i>Critical</span></div>${histogram(assets,{max:Math.max(125,...assets.map(a=>a.rul||0))})}`,'Each bar groups engine endpoints by predicted remaining cycles.')}${panel('Fleet Health',donut(s),'Classification from quality-aware, persistent triage rules.')}</div><div class="panel-grid">${panel('Engine Degradation Trend',`<div id="dashboard-trend">${empty('Choose a recorded engine','The chart uses one engine’s observed history, never a line across unrelated engine IDs.','','activity')}</div>`,'Historical model predictions over observed cycles.',assets.length?`<select id="trend-engine" class="select" aria-label="Engine for degradation trend">${assets.slice(0,100).map(a=>`<option value="${esc(a.asset)}" ${state.trendAsset===a.asset?'selected':''}>${engineLabel(a)}</option>`).join('')}</select>`:'')}${panel('Pipeline Status',latest?`<div class="job-title"><strong>${pretty(latest.kind)}</strong>${badge(latest.status)}</div><p class="small muted" style="margin-top:13px">${esc(latest.id)}</p><div class="key-values"><div><span>Started</span><strong>${date(latest.started_at)}</strong></div><div><span>Completed</span><strong>${date(latest.finished_at)}</strong></div><div><span>Last successful run</span><strong>${date(data.last_successful_run?.finished_at||data.last_successful_run)}</strong></div><div><span>Execution scope</span><strong>${state.mode==='demo'?'Synthetic examples':'Historical benchmark replay'}</strong></div></div>${latest.error?`<p class="inline-error">${esc(latest.error)}</p>`:''}<div class="actions" style="margin-top:18px">${button('Inspect run','job-detail','eye','small soft',`data-id="${esc(latest.id)}"`)}</div>`:empty('Pipeline is ready','Start a historical replay once an active model exists, or run a labelled demonstration.','','network'),'Real job status and execution timestamps.')}</div><div class="equal-grid"><section class="panel"><div class="table-toolbar"><h2>Recent Anomaly Alerts</h2><a class="text-button" href="/analytics" data-nav>View analytics ${icon('arrow-right')}</a></div>${recentAlerts(assets)}</section><section class="panel"><div class="table-toolbar"><h2>Recent Work Orders</h2><a class="text-button" href="/work-orders" data-nav>View all ${icon('arrow-right')}</a></div>${recentOrders(data.orders||[])}<div class="panel-footer">Simulated local maintenance records · no external dispatch</div></section></div>`+engineTable(assets,{compact:true});
}
function enginesPage(data){return heading('Engine Explorer','Explore individual engines, sensor quality, anomaly evidence, and remaining life.',button('Run pipeline','pipeline-dialog','play','primary'))+filterBar()+engineTable(data.items||[]);}

function engineDetailsPage(data){
  const a=data.asset,history=data.history||[],sensors=data.sensors||[],orders=data.orders||[],decisions=data.decisions||[];
  const chartSeries=[{key:'rul',label:'Predicted RUL',color:colors.orange}];if(history.some(p=>p.true_rul!=null))chartSeries.unshift({key:'true_rul',label:'Official evaluation RUL',color:colors.blue});
  const selected=sensors.find(s=>s.key===state.selectedSensor)||sensors.find(s=>s.index===3)||sensors[0];if(selected)state.selectedSensor=selected.key;
  const meta=`<img class="engine-photo" src="/assets/turbofan-hero.png" alt="Illustrative turbofan engine"><div class="key-values"><div><span>Engine ID</span><strong>${engineLabel(a)}</strong></div><div><span>Subset</span><strong>${a.subset}</strong></div><div><span>Observed cycle</span><strong>${num(a.cycle)}</strong></div><div><span>Predicted RUL</span><strong style="color:#FF8A24">${num(a.rul,1)} cycles</strong></div><div><span>Health status</span><strong>${badge(health(a))}</strong></div><div><span>Model version</span><strong class="mono">${esc(a.bundle_id)}</strong></div><div><span>Inference recorded</span><strong>${date(a.timestamp)}</strong></div></div><div class="divider"></div><p class="tiny muted">${esc(data.source_label)}. Engine imagery is illustrative.</p>`;
  const metrics=`<div class="detail-metrics">${[['Remaining life',num(a.rul,1)+' cycles','orange'],['Capped interval',a.lower==null?'Unavailable':num(a.lower)+'–'+num(a.upper),''],['Anomaly percentile',a.anomaly==null?'—':num(a.anomaly*100,1)+'%',''],['Trusted observations',num((a.quality??0)*100)+'%','']].map(([label,value,cls])=>`<div class="detail-metric"><span>${label}</span><strong class="${cls}">${value}</strong></div>`).join('')}</div>`;
  const prediction=panel('RUL Prediction',lineChart(history,{series:chartSeries,band:true,label:`Remaining useful life history for ${engineLabel(a)}`})+'<p class="chart-caption">Ground truth, when available, is used only for benchmark evaluation and never enters the triage packet. Intervals apply to capped RUL.</p>','Each prediction uses only the available sensor prefix.');
  const sensorSummary=panel('Sensor Health Indicators',sensors.slice(0,6).map(s=>`<div class="sensor-row"><div><strong>${esc(s.symbol||s.key)}</strong><small>${esc(s.label)} · ${num(s.value,2)} ${esc(s.unit||'')}</small></div>${sparkline(s.series||[])}</div>`).join('')||empty('No sensor history','Recorded sensor series will appear here.'),'NASA schema labels, with recorded units.');
  const operating=panel('Operating Settings',`<div class="key-values">${(data.operating_settings||[]).map((s,i)=>`<div><span>${esc(s.label||s.name||s.key||'Operating setting '+(i+1))}</span><strong>${num(s.value??s,3)} ${esc(s.unit||'')}</strong></div>`).join('')}</div>`,'Three recorded operating-condition inputs.');
  const decisionMarkup=decisions.length?decisions.slice(-12).reverse().map(d=>{const item=d.decision||d;return `<article class="job-card"><div class="job-title"><strong>Cycle ${num(d.cycle??item.inputs?.cycle)}</strong>${badge(item.severity||item.state||'attention')}</div><p>${esc(item.reason||item.explanation||'Recorded rule decision')}</p><div class="small muted">${esc(item.recommended_action||'Review recorded evidence')}</div><details><summary>Rules and inputs</summary>${(item.rules_evaluated||[]).map(r=>`<div class="rule-row"><span>${esc(pretty(r.rule||r.name))}</span><strong class="${r.matched?'':'not-matched'}">${r.evaluated===false?'Not evaluated':r.matched?'Matched':'Not matched'}</strong></div>`).join('')}<pre class="json-block">${esc(JSON.stringify({inputs:item.inputs||{},policy:item.policy_snapshot||{}},null,2))}</pre></details></article>`}).join(''):empty('No committed decisions yet','Run the pipeline to record rules, explanations, and maintenance recommendations.','','network');
  let content;
  if(state.detailTab==='sensors')content=`<div class="sensor-grid">${sensors.map(s=>`<article class="sensor-card"><h3>${esc(s.symbol||s.key)} · ${esc(s.key)}</h3><p>${esc(s.label)}</p><strong>${num(s.value,2)} <span class="tiny muted">${esc(s.unit||'')}</span></strong>${sparkline(s.series||[])}</article>`).join('')}</div>`;
  else if(state.detailTab==='predictions')content=prediction+`<div style="margin-top:20px">${notice('A planning signal, not a guaranteed failure date.','RUL and interval thresholds are engineering assumptions for the demonstration. Capped values near 125 may indicate a longer remaining horizon.','warning')}</div>`;
  else if(state.detailTab==='decisions')content=panel('Triage Decision History',decisionMarkup,'Input snapshots, evaluated rules, and recorded recommendations.');
  else if(state.detailTab==='orders')content=`<section class="panel"><div class="table-toolbar"><h2>Associated Work Orders</h2></div>${recentOrders(orders,100)}</section>`;
  else content=`${metrics}<div class="detail-main-grid">${prediction}${sensorSummary}</div>${selected?panel('Sensor Trend',lineChart(selected.series||[],{series:[{key:'value',label:selected.symbol||selected.key,color:colors.blue}],label:selected.label,yLabel:selected.unit||'recorded units',band:false,zero:false}),esc(selected.label),`<select id="sensor-select" class="select" aria-label="Sensor trend">${sensors.map(s=>`<option value="${esc(s.key)}" ${selected.key===s.key?'selected':''}>${esc(s.key)} · ${esc(s.symbol||s.label)}</option>`).join('')}</select>`):''}<div style="margin-top:20px">${operating}</div>`;
  return `<div class="breadcrumbs"><a href="/engines" data-nav>Engines</a>${icon('chevron-right')}<span>Engine ${engineLabel(a)}</span></div>`+heading(`Engine #${engineLabel(a)}`,'Observed histories, measured predictions, and the evidence behind each action.',`<select id="history-limit" class="select" aria-label="History cycle count">${[30,60,150].map(n=>`<option value="${n}" ${n===state.detailLimit?'selected':''}>Last ${n} cycles</option>`).join('')}</select>${badge(health(a))}`)+(!a.quality_valid?notice('Prediction requires engineering review',esc(a.quality_reason||'Data quality or uncertainty is outside the configured support gate.'),'warning'):'')+`<div class="tabs" role="tablist" aria-label="Engine details">${[['overview','Overview'],['sensors','Sensor Data'],['predictions','RUL Prediction'],['decisions','Decisions'],['orders','Work Orders']].map(([key,label])=>`<button class="tab ${state.detailTab===key?'active':''}" data-action="engine-tab" data-value="${key}" role="tab" aria-selected="${state.detailTab===key}">${label}</button>`).join('')}</div><div class="engine-detail-grid"><aside class="panel"><div class="panel-body">${meta}</div></aside><div>${content}</div></div>`;
}

function analyticsPage(data){
  const runs=(data.runs||[]).filter(r=>state.subset==='ALL'||r.subset===state.subset),assets=data.assets||[],s=data.summary||{},metrics=runs.filter(r=>r.evaluation?.metrics);
  return heading('Anomaly & RUL Analytics','Inspect measured fleet behavior, evaluation results, and the limits of the evidence.',link('Compare models','/models','git-compare-arrows'))+filterBar()+`<div class="panel-grid">${panel('Anomaly Score Distribution',histogram(assets,{metric:'anomaly',max:1,bins:12,label:'Empirical anomaly score distribution'}),'Percentiles relative to an initial healthy-prefix reference.')}${panel('Fleet Classification',donut(s),'Rule outcomes, including unknown or unsupported evidence.')}</div>`+notice('Anomaly scores are not fault probabilities.','Isolation Forest is fitted independently on initial healthy-prefix windows from fit engines. C-MAPSS has no separate timestamped anomaly labels; labelled-fault detection accuracy is not claimed.')+`<section class="panel"><div class="table-toolbar"><h2>Measured Model Performance by Subset</h2><span class="source-pill">ORIGINAL TEST ENDPOINTS</span></div>${metrics.length?`<div class="table-scroll"><table><thead><tr><th>SUBSET / RUN</th><th>RMSE · CYCLES</th><th>MAE · CYCLES</th><th>R²</th><th>NASA SCORE ↓</th><th>ENGINES</th></tr></thead><tbody>${metrics.map(r=>{const m=r.evaluation.metrics;return `<tr><td>${tag(r.subset)}<div class="mono" style="margin-top:5px">${esc(r.run_id)}</div></td><td>${num(m.rmse,2)}</td><td>${num(m.mae,2)}</td><td>${num(m.r2,3)}</td><td>${num(m.nasa_score,2)}</td><td>${num(m.n_engines)}</td></tr>`}).join('')}</tbody></table></div>`:empty('No official test evaluation yet','Train and evaluate a baseline to see real per-subset metrics. Published scores are never substituted for model results.',link('Train a baseline','/models','brain-circuit','soft'))}<div class="panel-footer">Lower RMSE, MAE, and NASA score are better. NASA penalizes optimistic / late RUL errors more strongly.</div></section><div style="height:20px"></div>${panel('Recent Engine Alerts',recentAlerts(assets),'Inspect the underlying engine history before drawing a maintenance conclusion.')}<div style="height:20px"></div>${panel('Monitoring Scope','<div class="key-values"><div><span>Operational data</span><strong>Historical benchmark replay</strong></div><div><span>Performance monitoring</span><strong>Saved run and evaluation history</strong></div><div><span>Data drift</span><strong>No operational drift detector claimed</strong></div><div><span>Model promotion</span><strong>Development metrics, before test truth</strong></div></div>','Current implementation boundaries are explicit.')}`;
}

function comparisonMarkup(runs){const selected=runs.filter(r=>state.comparison.has(r.run_id));if(selected.length<2)return '';return panel('Model Comparison',`<div class="table-scroll"><table class="comparison-table"><thead><tr><th>METRIC</th>${selected.map(r=>`<th>${r.subset}<br><span class="mono">${esc(r.run_id)}</span></th>`).join('')}</tr></thead><tbody>${[['Development capped RMSE',r=>r.validation_metrics?.capped_rmse??r.validation_metrics?.rmse],['Official test RMSE',r=>r.evaluation?.metrics?.rmse],['Official test MAE',r=>r.evaluation?.metrics?.mae],['Official test R²',r=>r.evaluation?.metrics?.r2],['Official test NASA score',r=>r.evaluation?.metrics?.nasa_score]].map(([name,get])=>`<tr><td>${name}</td>${selected.map(r=>`<td><strong>${num(get(r),3)}</strong></td>`).join('')}</tr>`).join('')}</tbody></table></div>`,'Development metrics determine promotion. Test metrics are reported separately.','','compare-panel');}
function modelsPage(data){const active=data.active||{},runs=[...(data.runs||[])].filter(r=>state.subset==='ALL'||r.subset===state.subset).sort((a,b)=>Number(active[b.subset]===b.run_id)-Number(active[a.subset]===a.run_id));return heading('Model Registry & MLOps','GPU research, measured baseline runs, and validation-controlled comparisons.','<a class="button primary" href="/downloads/kan-notebook">GPU training notebook</a>'+button('Train a baseline','train-dialog','plus','',state.mode==='demo'?'disabled':''))+researchOverview(data.gpu_research||{},state.subset)+'<h2 class="research-baseline-label">CPU benchmark models</h2>'+notice('Measured benchmark models · promotion follows development evidence.','This registry always shows actual training runs, including when Demo examples are selected for engine views. Candidates must pass development RMSE and NASA-score criteria. Test results never choose the active model; previous promoted versions are retained.')+`<div id="comparison-panel">${comparisonMarkup(runs)}</div>`+(runs.length?runs.map(r=>{const a=active[r.subset]===r.run_id,m=r.evaluation?.metrics||{},v=r.validation_metrics||{},previous=(data.promotions||[]).find(p=>p.subset===r.subset&&p.run_id===r.run_id)?.previous_run_id;return `<article class="model-card"><div class="model-title"><h3>${tag(r.subset)}${esc(r.family||'Histogram gradient boosting + Isolation Forest')}</h3><div class="actions">${a?'<span class="tag green">Active model</span>':''}${badge(r.training_status)}<label class="compare-select"><input type="checkbox" data-model-compare="${esc(r.run_id)}" ${state.comparison.has(r.run_id)?'checked':''}>Compare</label></div></div><p class="mono" style="margin:10px 0 0">${esc(r.run_id)} · ${date(r.finished_at||r.created_at)}</p><div class="model-metrics">${[['Dev capped RMSE',v.capped_rmse??v.rmse],['Test RMSE',m.rmse],['Test MAE',m.mae],['Test R²',m.r2],['Test NASA score ↓',m.nasa_score]].map(([label,value])=>`<div><span>${label}</span><strong>${num(value,label.includes('R²')?3:2)}</strong></div>`).join('')}</div><p class="model-copy">${esc(r.promotion_reason||'Promotion eligibility is determined from development evidence.')} ${r.mlflow_run_id?'MLflow run: '+esc(r.mlflow_run_id)+'.':''}</p><div class="model-actions">${button('Run details','model-detail','eye','small',`data-id="${esc(r.run_id)}"`)}<a class="button small" href="/api/models/${encodeURIComponent(r.run_id)}/download">${icon('download')}Artifacts</a>${!a?button('Promote candidate','promote','shield-check','small soft',`data-id="${esc(r.run_id)}" ${r.promotion_eligible===false?'disabled':''}`):''}${button('Retrain subset','retrain','refresh-cw','small',`data-subset="${r.subset}" ${state.mode==='demo'?'disabled':''}`)}${a&&previous?button('Restore previous','rollback','rotate-ccw','small',`data-id="${esc(previous)}"`):''}</div></article>`}).join(''):`<section class="panel">${empty('Your model registry is ready','Train the CPU baseline on an imported NASA subset. Measured metrics and immutable artifacts appear here only after actual execution.',button('Configure baseline training','train-dialog','brain-circuit','soft',state.mode==='demo'?'disabled':''),'boxes')}</section>`)+`<div style="height:20px"></div>${panel('Earlier integrated experiment','<p class="small muted">The earlier multi-paper notebook is retained for reference. The selected research workflow above uses Transformer–KAN–BiLSTM, a controlled condition-gate ablation, and SHAP/LIME after evaluation.</p><a class="text-link" href="/downloads/legacy-notebook">Download earlier integrated notebook</a>','Archived experiment; no measured neural gain claimed.')}`;}

function orderTable(orders){const matches=orders.filter(o=>(state.subset==='ALL'||(o.subset||o.asset.split('/')[0])===state.subset)&&(state.orderStatus==='all'||o.status===state.orderStatus)&&(state.orderPriority==='ALL'||o.priority===state.orderPriority)&&`${o.id} ${o.asset} ${o.owner||''}`.toLowerCase().includes(state.orderSearch.toLowerCase())),size=20,total=matches.length,page=Math.min(state.orderPage,Math.max(0,Math.ceil(total/size)-1)),shown=matches.slice(page*size,(page+1)*size);return `<section class="panel"><div class="table-toolbar"><h2>${num(total)} Work Orders</h2><div class="table-tools"><label class="input-search">${icon('search')}<span class="sr-only">Search work orders</span><input id="order-search" placeholder="Search order, engine, owner…" value="${esc(state.orderSearch)}"></label><label class="sr-only" for="order-priority">Priority</label><select class="select" id="order-priority"><option value="ALL">All priorities</option>${['CRITICAL','HIGH','MEDIUM'].map(p=>`<option ${state.orderPriority===p?'selected':''}>${p}</option>`).join('')}</select></div></div><div class="table-scroll"><table><thead><tr><th>WORK ORDER / ENGINE</th><th>PRIORITY</th><th>RUL AT CREATION</th><th>STATUS</th><th>OWNER</th><th>CREATED</th><th>ACTIONS</th></tr></thead><tbody>${shown.length?shown.map(o=>`<tr><td><button class="text-button" data-action="order-detail" data-id="${esc(o.id)}">${esc(o.id)}</button><small style="display:block;font-size:8px;margin-top:5px">${esc(o.asset)}</small></td><td>${badge(o.priority)}</td><td>${num(o.predicted_rul??o.evidence?.rul,1)} cycles</td><td>${badge(o.status)}</td><td>${esc(o.owner||'Unassigned')}</td><td>${date(o.created_at)}</td><td><div class="actions">${button('View','order-detail','eye','small',`data-id="${esc(o.id)}"`)}${o.status==='open'?button('Acknowledge','ack-order','check','small',`data-id="${esc(o.id)}"`):''}${o.status!=='resolved'?button('Manage','manage-order','wrench','small soft',`data-id="${esc(o.id)}"`):''}</div></td></tr>`).join(''):`<tr><td colspan="7">${empty('No matching work orders','Run the pipeline or adjust the search and status filters. Work orders are simulated local records.','','clipboard-list')}</td></tr>`}</tbody></table></div><div class="table-pagination"><span>Showing ${total?page*size+1:0}–${Math.min(total,(page+1)*size)} of ${total} orders</span><div class="actions">${button('Previous','order-prev','chevron-right','small',page===0?'disabled':'')}${button('Next','order-next','arrow-right','small',(page+1)*size>=total?'disabled':'')}</div></div></section>`;}
function ordersPage(data){const orders=(data.items||[]).filter(o=>state.subset==='ALL'||(o.subset||o.asset.split('/')[0])===state.subset);return heading('Maintenance Work Orders','Turn persistent model evidence into traceable maintenance outcomes.',button('Run triage pipeline','pipeline-dialog','play','primary'))+metricCards([['Total Records',num(orders.length),'Simulated maintenance records','clipboard-list',''],['Open',num(orders.filter(o=>o.status==='open').length),'Awaiting acknowledgement','circle-alert','orange'],['In Progress',num(orders.filter(o=>['in_progress','acknowledged'].includes(o.status)).length),'Acknowledged or underway','wrench',''],['Resolved',num(orders.filter(o=>o.status==='resolved').length),'Explicit outcomes recorded','check-check','green']])+`<div class="tabs" aria-label="Work order status">${[['all','All orders'],['open','Open'],['acknowledged','Acknowledged'],['in_progress','In progress'],['resolved','Resolved']].map(([k,v])=>`<button class="tab ${state.orderStatus===k?'active':''}" data-action="order-status" data-value="${k}" aria-pressed="${state.orderStatus===k}">${v}</button>`).join('')}</div>`+notice('Simulated local maintenance workflow.','Automatic order creation, ownership, status changes, and resolution are saved locally. No external maintenance system receives a dispatch.')+`<div id="orders-table">${orderTable(orders)}</div>`;}

const stages=['Dataset ingestion','Validation & cleaning','Feature engineering','Anomaly detection','RUL inference','Rule-based triage','Work-order creation','Tracking & monitoring'];
function stageMarkup(stage,index){return `<article class="stage-card ${esc(stage?.status||'')}"><span class="stage-number">${stage?.status==='complete'?icon('check'):String(index+1).padStart(2,'0')}</span><h3>${esc(stage?.name?pretty(stage.name):stages[index])}</h3>${badge(stage?.status||'Not run',''+(stage?.status||'unknown'))}<p>${stage?`${num(stage.records||0)} records · ${num(stage.duration_seconds,2)}s<br>${esc(stage.subset||'')}`:'Awaiting a recorded pipeline execution.'}</p></article>`;}
function jobStages(job){return job?.stages?.length?`<div class="stage-timeline">${job.stages.map(s=>`<div class="stage-event ${esc(s.status)}">${icon(s.status==='complete'?'circle-check':s.status==='failed'?'circle-alert':s.status==='running'?'loader-circle':'clock')}<div><h3>${esc(pretty(s.name))} ${s.subset?tag(s.subset):''}</h3><p>${esc(s.error||s.detail||'Execution details recorded by the pipeline.')}</p><small>${date(s.started_at)} · ${num(s.records||0)} records · ${num(s.duration_seconds,3)} seconds</small></div>${badge(s.status)}</div>`).join('')}</div>`:empty('No execution stages yet','Queued work will report its actual stages and durations here.','','network');}
function pipelinePage(data){const jobs=data.items||[],selected=data.selected||null;return heading('Pipeline Execution & Triage','Inspect every stage from validated sensor records to persisted maintenance decisions.',`${button('Run pipeline','pipeline-dialog','play','primary')}${button('Refresh','refresh','refresh-cw')}`)+notice('Every status comes from a recorded job.','Long-running work runs in the background. Idempotency keys prevent repeated clicks from starting duplicate jobs. Failed or interrupted runs can be retried explicitly.')+`<div class="pipeline-grid">${(selected?.stages?.length?selected.stages:stages.map(()=>null)).map((stage,i)=>stageMarkup(stage,i)).join('')}</div><div class="panel-grid">${panel('Execution Details',selected?`<div class="job-title"><strong>${esc(selected.id)}</strong>${badge(selected.status)}</div><p class="small muted" style="margin-top:10px">${pretty(selected.kind)} · ${date(selected.started_at||selected.created_at)}</p>${selected.error?`<p class="inline-error">${esc(selected.error)}</p>`:''}${jobStages(selected)}${['failed','interrupted'].includes(selected.status)?`<div class="actions" style="margin-top:15px">${button('Retry safely','retry-job','refresh-cw','soft',`data-id="${esc(selected.id)}"`)}</div>`:''}`:empty('No pipeline run selected','Start a run or choose one from the execution history.','','network'),'Actual statuses, record counts, durations, and errors.')}${panel('Run History',jobs.length?jobs.map(j=>`<article class="job-card"><div class="job-title"><strong>${pretty(j.kind)}</strong>${badge(j.status)}</div><p>${date(j.created_at)} · ${esc(j.configuration?.subsets?.join(', ')||'')}</p><div class="actions">${button('Inspect','select-job','eye','small soft',`data-id="${esc(j.id)}"`)}<span class="job-id">${esc(j.id)}</span></div></article>`).join(''):empty('Your run history is empty','Pipeline and training jobs appear here after you explicitly start them.','','clock'),'Immutable inputs and recoverable execution records.')}</div>`;}

function dataPage(data){const ds=data.datasets||[],preview=data.preview;return heading('Dataset Management','Validate, inspect, and prepare FD001–FD004 without crossing the train/test boundary.',`${button('Upload dataset','upload-dialog','upload','primary')}${button('Prepare features','prepare-dialog','settings')}`)+`<div class="dataset-grid">${ds.map(d=>`<article class="dataset-card"><div class="job-title">${tag(d.subset)}<span class="ready-mark ${d.ready?'':'pending'}">${icon(d.ready?'circle-check':'clock')}${d.ready?'Validated':'Missing files'}</span></div><h3>${d.subset}</h3><p>${d.conditions} operating condition${d.conditions===1?'':'s'} · ${d.fault_modes} fault mode${d.fault_modes===1?'':'s'}</p><div class="data-pair"><span>Training engines</span><strong>${d.ready?num(d.train_engines):'—'} / ${d.expected_train}</strong></div><div class="data-pair"><span>Test engines</span><strong>${d.ready?num(d.test_engines):'—'} / ${d.expected_test}</strong></div><div class="data-pair"><span>Sensor rows</span><strong>${num(d.rows||0)}</strong></div><div class="data-pair"><span>Files available</span><strong>${d.files?.length||0} / 3</strong></div>${d.errors?.length?`<p class="inline-error">${esc(d.errors.join('; '))}</p>`:''}${d.ready&&d.official_counts_match===false?'<p class="inline-error">Counts differ from the reference benchmark. This is treated as a custom corpus.</p>':''}${button('Inspect data','preview-data','eye','small',`data-subset="${d.subset}"`)}</article>`).join('')}</div>`+notice('Training labels and test targets serve different roles.',esc(data.label_note||'Training RUL is derived from complete run-to-failure trajectories. The RUL_*.txt files provide official test-endpoint evaluation targets; they are never training features.'))+`<section class="panel"><div class="table-toolbar"><div><h2>Data Preview · ${state.previewSubset}</h2><p class="tiny muted" style="margin:4px 0 0">Raw schema, missing-value analysis, and split information.</p></div><div class="table-tools"><select class="select" id="preview-subset" aria-label="Preview subset">${subsets.map(s=>`<option ${state.previewSubset===s?'selected':''}>${s}</option>`).join('')}</select><select class="select" id="preview-partition" aria-label="Preview partition">${[['train','Training sensor records'],['test','Test sensor records'],['RUL','Test endpoint truth']].map(([k,v])=>`<option value="${k}" ${state.previewPartition===k?'selected':''}>${v}</option>`).join('')}</select>${button('CSV schema','download-schema','download','small')}</div></div>${preview?previewMarkup(preview):empty('Select an available dataset','Imported source records are previewed without generating synthetic measurements.','','database')}</section><div style="height:20px"></div>${panel('Provenance & Data Boundaries',`<p class="small muted">${esc(data.schema_note||'26 fields: unit, cycle, three operating settings, and 21 sensor measurements. Values retain their source meaning.')}</p><details><summary>Inspect dataset provenance and source hashes</summary><pre class="json-block">${esc(JSON.stringify(data.provenance||{status:'No source manifest available'},null,2))}</pre></details><div class="actions"><a class="button small" href="https://data.nasa.gov/dataset/cmapss-jet-engine-simulated-data" target="_blank" rel="noopener">NASA source ${icon('arrow-up-right')}</a><a class="button small" href="/downloads/notebook">${icon('download')}Training notebook</a></div>`,'Original files, source dates, and provenance limitations stay inspectable.')}`;}
function previewMarkup(p){const stats=p.statistics||{},columns=p.columns||[],rows=p.rows||[],getName=c=>typeof c==='object'?c.name:c;return `<div class="panel-body"><div class="key-values" style="grid-template-columns:repeat(3,minmax(0,1fr));gap:15px"><div><span>Rows</span><strong>${num(stats.rows)}</strong></div><div><span>Engines</span><strong>${num(stats.engine_count)}</strong></div><div><span>Missing values</span><strong>${num(stats.missing_values||0)}</strong></div><div><span>Duplicate records</span><strong>${num(stats.duplicate_records||0)}</strong></div><div><span>Invalid records</span><strong>${num(stats.invalid_records||0)}</strong></div><div><span>Observed cycle range</span><strong>${num(stats.cycle_min)}–${num(stats.cycle_max)}</strong></div></div>${stats.errors?.length?`<p class="inline-error">${esc(stats.errors.join('; '))}</p>`:''}</div><div class="table-scroll"><table><thead><tr>${columns.map(c=>`<th title="${esc(c.label||getName(c))}">${esc(getName(c))}${c.symbol?`<br><span style="font-size:7px">${esc(c.symbol)}</span>`:''}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${columns.map((c,i)=>`<td>${row?.[i]==null&&Array.isArray(row)||!Array.isArray(row)&&row[getName(c)]==null?'<span class="tag orange">Missing</span>':esc(num(Array.isArray(row)?row[i]:row[getName(c)],3))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="panel-footer"><span>First ${rows.length} source records · ${esc(p.partition||state.previewPartition)}</span><span>${esc(stats.label_role||p.source_label||'Raw observations')}</span></div><div class="panel-body"><details><summary>Missing-value analysis by column</summary><pre class="json-block">${esc(JSON.stringify(stats.missing_by_column||{},null,2))}</pre></details><details><summary>Engine-disjoint split information</summary>${p.split?`<div class="key-values">${Object.entries(p.split).map(([name,ids])=>`<div><span>${esc(pretty(name))}</span><strong>${Array.isArray(ids)?ids.length+' engines':esc(ids)}</strong></div>`).join('')}</div><pre class="json-block">${esc(JSON.stringify(p.split,null,2))}</pre>`:'<p class="small muted">Prepare features or train a model to record an engine-disjoint fit, selection, and calibration manifest.</p>'}</details></div>`;}

function settingsPage(value){const policyInfo=[['critical_rul','Immediate critical RUL',0,30,.5],['critical_lower','Critical lower interval',0,40,.5],['critical_upper','Critical upper interval',0,40,.5],['attention_lower','Attention lower interval',5,100,1],['watch_lower','Watch lower interval',10,125,1],['anomaly_attention','Attention anomaly percentile',.8,1,.001],['anomaly_extreme','Extreme anomaly percentile',.8,1,.001],['trend_threshold','Normalized trend threshold',.001,2,.001],['persistence','Attention persistence · cycles',1,20,1],['critical_persistence','Critical persistence · cycles',1,10,1],['rearm_cycles','Healthy rearm · cycles',2,30,1]];return heading('Application & Pipeline Settings','Configure the local workspace, rule assumptions, and model promotion safeguards.')+`<div class="settings-layout"><form class="panel" id="settings-form"><section class="settings-section"><h2>Workspace</h2><p>Local research preferences. This application does not represent an authenticated enterprise account.</p><div class="form-grid"><label class="field">Workspace name<input name="workspace_name" maxlength="60" required value="${esc(value.workspace_name)}"></label><label class="field">Researcher name<input name="researcher_name" maxlength="60" required value="${esc(value.researcher_name)}"></label><label class="field">Default subset<select name="default_subset"><option value="ALL">All datasets</option>${subsets.map(s=>`<option ${value.default_subset===s?'selected':''}>${s}</option>`).join('')}</select></label></div></section><section class="settings-section"><h2>Rule-Based Triage</h2><p>Thresholds are engineering assumptions for historical demonstration. Changes apply to future decisions; archived evidence is immutable. Anomaly scores are empirical percentiles, not failure probabilities.</p><div class="form-grid three">${policyInfo.map(([key,label,min,max,step])=>`<label class="field">${label}<input type="number" name="policy.${key}" min="${min}" max="${max}" step="${step}" required value="${value.policy[key]}"></label>`).join('')}</div></section><section class="settings-section"><h2>Pipeline & Model Promotion</h2><p>Automatic promotion compares candidates on fixed development cohorts. A worse candidate is retained for inspection without replacing the active model.</p><div class="form-grid"><label class="field">Replay window · cycles<input type="number" min="3" max="150" name="replay_cycles" required value="${value.replay_cycles}"></label><label class="field">Maximum decision interval width · cycles<input type="number" min="10" max="250" name="uncertainty_gate" required value="${value.uncertainty_gate}"></label><label class="field">RMSE regression tolerance · %<input type="number" min="0" max="10" step=".1" name="promotion_rmse_tolerance_percent" required value="${value.promotion_rmse_tolerance_percent}"></label><label class="field">NASA score regression tolerance · %<input type="number" min="0" max="20" step=".1" name="promotion_nasa_tolerance_percent" required value="${value.promotion_nasa_tolerance_percent}"></label></div><p class="form-error" id="settings-error" role="alert"></p></section><div class="settings-footer">${button('Load defaults','settings-defaults','rotate-ccw')}<button type="submit" class="button primary">${icon('check')}Save settings</button></div></form><aside>${panel('Your Configuration','<div class="key-values"><div><span>Storage</span><strong>Local SQLite</strong></div><div><span>Triage implementation</span><strong>Python rules</strong></div><div><span>External dispatch</span><strong>Not connected</strong></div><div><span>Physical live stream</span><strong>Historical replay only</strong></div><div><span>Model promotion</span><strong>Development-gated</strong></div></div>','Settings and changes persist locally.')}</aside></div>`;}

async function render({loading=true}={}){
  const generation=++state.generation;state.route=location.pathname.replace(/\/$/,'')||'/';
  const query=new URLSearchParams(location.search);
  const querySignature=state.route+location.search;
  if(state.querySignature!==querySignature){
    if(query.has('subset')&&subsets.includes(query.get('subset')))state.previewSubset=query.get('subset');
    if(state.route==='/engines'&&query.has('q'))state.engineSearch=query.get('q');
    if(state.route==='/work-orders'&&query.has('q'))state.orderSearch=query.get('q');
    state.querySignature=querySignature;
  }
  if(loading){$('#app').innerHTML=state.route==='/'?'<main id="main" class="initial-loading"><div class="loader"></div><p>Loading AeroGuard…</p></main>':shell();if(state.route!=='/')$('#main').innerHTML='<div class="page-loading"><div class="loader"></div><p>Loading your workspace…</p></div>';}
  try{
    if(!state.settings){try{state.settings=await api('/settings');}catch{state.settings=structuredClone(defaults);}}
    let data,markup;
    if(state.route==='/'){try{data=await api('/dashboard?'+modeQuery());}catch{data=null;}if(generation!==state.generation)return;state.data=data;$('#app').innerHTML=landingMarkup(data);document.title='AeroGuard · Predictive Maintenance Intelligence';return;}
    const route=state.route.split('/')[1];
    if(route==='dashboard'){data=await api('/dashboard?'+filters());markup=dashboardPage(data);}
    else if(route==='engines'&&state.route.split('/').length>2){const asset=decodeURIComponent(state.route.slice('/engines/'.length));data=await api('/engines/'+encodeURIComponent(asset)+'?'+modeQuery()+'&limit='+state.detailLimit);markup=engineDetailsPage(data);}
    else if(route==='engines'){data=await api('/engines?'+filters());markup=enginesPage(data);}
    else if(route==='analytics'){data=await api('/analytics?'+filters());markup=analyticsPage(data);}
    else if(route==='models'){if(query.get('research')){data=await api('/research/runs/'+encodeURIComponent(query.get('research')));const engine=Number(query.get('engine'))||data.explanation_engines?.[0]?.engine_id||data.predictions?.[0]?.engine_id;data.engine=await api('/research/runs/'+encodeURIComponent(data.run_id)+'/engines/'+engine);markup=researchResults(data,data.engine);}else{data=await api('/models');markup=modelsPage(data);}}
    else if(route==='work-orders'){data=await api('/orders?'+modeQuery());markup=ordersPage(data);}
    else if(route==='pipeline'){data=await api('/jobs?'+modeQuery());if(state.subset!=='ALL')data.items=(data.items||[]).filter(j=>j.configuration?.subsets?.includes(state.subset)||j.configuration?.version_id?.includes(state.subset)||j.configuration?.run_id?.includes(state.subset));if(data.items?.length){const selectedId=data.items.some(j=>j.id===state.jobId)?state.jobId:data.items[0].id;try{data.selected=await api('/jobs/'+encodeURIComponent(selectedId));}catch{data.selected=null;}}markup=pipelinePage(data);}
    else if(route==='data'){data=await api('/data');try{data.preview=await api(`/data/${state.previewSubset}/preview?partition=${state.previewPartition}&limit=15`);}catch(error){data.previewError=error.message;}markup=dataPage(data)+(data.previewError?`<p class="inline-error">${esc(data.previewError)}</p>`:'');}
    else if(route==='settings'){data=await api('/settings');state.settings=data;markup=settingsPage(data);}
    else{data={};markup=heading('Page not found','Choose a workspace page from the navigation.')+link('Back to dashboard','/dashboard','arrow-right','primary');}
    if(['models','pipeline','data','settings'].includes(route)&&!query.get('research')){let lifecycle;try{lifecycle=await api('/mlops');}catch(error){lifecycle={error:error.message};}markup+=mlopsMarkup(lifecycle,{panel,esc,num,date,button,notice,subset:state.subset,mode:state.mode});}
    if(generation!==state.generation)return;
    state.data=data;$('#app').innerHTML=shell();$('#main').innerHTML=markup;document.title=`${routeInfo[route]?.[0]||'Workspace'} · AeroGuard`;$('#announcer').textContent=`${routeInfo[route]?.[0]||'Workspace'} loaded. ${state.mode==='demo'?'Synthetic demonstration examples.':'Historical benchmark data.'}`;
    if(route==='dashboard')loadTrend(data.assets||[]);
    if(route==='work-orders'&&query.get('order'))orderDialog(query.get('order'));
  }catch(error){if(generation!==state.generation)return;if(!$('.shell'))$('#app').innerHTML=shell();$('#main').innerHTML=heading('Workspace unavailable','The service returned a problem that needs attention.')+`<div class="error-box">${esc(error.message)}<br>${button('Try again','refresh','refresh-cw','small')}</div>`;}
}
async function loadTrend(assets){const container=$('#dashboard-trend');if(!container||!assets.length)return;container.innerHTML='<div class="chart-empty"><div class="loader"></div><span style="margin-left:12px">Loading recorded engine history…</span></div>';const selected=assets.find(a=>a.asset===state.trendAsset)||assets[0];state.trendAsset=selected.asset;try{const d=await api('/engines/'+encodeURIComponent(selected.asset)+'?'+modeQuery()+'&limit=30');if(!$('#dashboard-trend')||state.trendAsset!==selected.asset)return;const series=[{key:'rul',label:'Predicted RUL',color:colors.orange}];if(d.history?.some(p=>p.true_rul!=null))series.unshift({key:'true_rul',label:'Evaluation truth',color:colors.blue});$('#dashboard-trend').innerHTML=lineChart(d.history||[],{series,band:true,label:'Historical remaining life for '+engineLabel(selected)})+`<p class="chart-caption">Engine ${engineLabel(selected)} · ${esc(d.source_label)}</p>`;}catch(error){if($('#dashboard-trend'))$('#dashboard-trend').innerHTML=`<p class="inline-error">${esc(error.message)}</p>`;}}

function openDialog(title,copy,content,{wide=false}={}){const dialog=$('#dialog');dialog.classList.toggle('wide',wide);delete dialog.dataset.jobId;$('#dialog-body').innerHTML=`<div class="dialog-header"><div><h2 id="dialog-title">${title}</h2>${copy?`<p>${copy}</p>`:''}</div><button type="button" class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('x')}</button></div>${content}`;if(!dialog.open)dialog.showModal();}
function closeDialog(){$('#dialog').close();delete $('#dialog').dataset.jobId;state.pendingConfirm=null;}
function confirmDialog(title,copy,action){state.pendingConfirm=action;openDialog(title,copy,`<form id="confirm-form"><label class="check-line"><input type="checkbox" required>I understand and confirm this change to the local workspace.</label><div class="dialog-footer">${button('Cancel','close-dialog')}<button class="button primary" type="submit">${icon('check')}Confirm</button></div><p class="form-error" id="confirm-error" role="alert"></p></form>`);}
function trainDialog(subset=null){
  if(state.mode==='demo'){toast('Select Benchmark data in the top bar to train a real model.');return;}
  const chosen=subset?[subset]:selectedSubsets(),retrain=Boolean(subset);
  openDialog(retrain?'Retrain a benchmark model':'Train a reproducible baseline','HistGradientBoosting RUL prediction + independently fitted Isolation Forest. The CUDA notebook remains available separately.',`<form id="train-form"><p class="dialog-copy">This starts actual CPU training on complete training trajectories, with fixed engine-disjoint fit, selection, and calibration cohorts. Official endpoint truth is used only after the predictor and promotion decision are frozen.</p><span class="field-label">Dataset subsets</span><div class="checkboxes">${subsets.map(s=>`<label><input type="checkbox" name="subsets" value="${s}" ${chosen.includes(s)?'checked':''}>${s}</label>`).join('')}</div><div class="form-grid"><label class="field">Boosting iterations<input type="number" name="iterations" min="10" max="500" value="100" required></label><label class="field">Random seed<input type="number" name="seed" min="0" max="2147483647" value="42" required></label></div><details><summary>Advanced reproducibility settings</summary><div class="form-grid"><label class="field">Learning rate<input type="number" name="learning_rate" min=".005" max=".5" step=".005" value=".08" required></label><label class="field">Maximum leaf nodes<input type="number" name="max_leaf_nodes" min="5" max="63" value="15" required></label><label class="field">Feature window · cycles<input type="number" name="window" min="5" max="60" value="30" required></label><label class="field">Training window stride<input type="number" name="stride" min="1" max="15" value="3" required></label><label class="field">Split seed<input type="number" name="split_seed" min="0" max="2147483647" value="42" required><small>Keep fixed when comparing training seeds.</small></label><label class="field">RUL cap · cycles<input type="number" name="cap" min="30" max="200" value="125" required></label><label class="field">Replay context · cycles<input type="number" name="replay_cycles" min="3" max="150" value="${state.settings?.replay_cycles||30}" required></label></div></details><label class="check-line"><input type="checkbox" name="promote" ${retrain?'':'checked'}>Promote only when development criteria pass, then replay the active model.</label><label class="check-line"><input type="checkbox" name="track_mlflow" checked>Track the actual experiment in local MLflow.</label><div class="dialog-footer">${button('Cancel','close-dialog')}<button class="button primary" type="submit">${icon('play')}${retrain?'Start retraining':'Start training'}</button></div><p class="form-error" id="train-error" role="alert"></p></form>`);
}
function pipelineDialog(kind='replay'){
  const prepare=kind==='prepare';
  openDialog(prepare?'Prepare dataset features':'Run the maintenance pipeline',prepare?'Validate inputs and record a fit-only preprocessing audit.':'Replay historical cycles through the active model, rule agent, and simulated work-order queue.',`<form id="pipeline-form" data-kind="${prepare?'prepare':'replay'}"><p class="dialog-copy">${prepare?'Data preparation fits only the training-engine cohort. It does not use official test targets.':'The pipeline records each stage and safely skips previously committed events. A missing active model produces an explicit error, never synthetic predictions.'}</p><span class="field-label">Dataset subsets</span><div class="checkboxes">${subsets.map(s=>`<label><input type="checkbox" name="subsets" value="${s}" ${selectedSubsets().includes(s)?'checked':''}>${s}</label>`).join('')}</div><label class="field">Observed history per engine · cycles<input type="number" name="cycles" min="3" max="150" value="${state.settings?.replay_cycles||30}" required></label>${!prepare?`<div class="notice ${state.mode==='demo'?'warning':''}">${icon('circle-alert')}<div><strong>${state.mode==='demo'?'Synthetic demonstration mode':'Benchmark replay mode'}</strong>${state.mode==='demo'?'Only explicitly labelled synthetic fixture packets are processed. No model training or benchmark performance is implied.':'Uses saved model artifacts and recorded C-MAPSS histories. Work orders remain simulated local records.'}</div></div>`:''}<div class="dialog-footer">${button('Cancel','close-dialog')}<button class="button primary" type="submit">${icon('play')}${prepare?'Start preparation':'Start pipeline'}</button></div><p class="form-error" id="pipeline-error" role="alert"></p></form>`);
}
function uploadDialog(){openDialog('Import a dataset','ZIP for all four official subsets, or a compatible CSV/TXT file for one partition.',`<form id="upload-form"><div class="upload-drop">${icon('upload')}<p>Choose original benchmark files or a compatible sensor batch.<br>Different existing file contents are never silently overwritten.</p><label class="sr-only" for="upload-file">Dataset file</label><input id="upload-file" name="file" type="file" accept=".zip,.csv,.txt" required></div><div class="form-grid"><label class="field">Subset for CSV / TXT<select name="subset">${subsets.map(s=>`<option ${state.previewSubset===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Partition<select name="partition"><option value="train">Training trajectories</option><option value="test">Test sensor histories</option><option value="RUL">Test endpoint RUL</option></select></label></div><p class="dialog-copy">Sensor files require unit, cycle, three settings, and 21 sensors. Test endpoint truth is a separate single-column file. ZIP imports require all 12 NASA train/test/RUL files.</p><div class="dialog-footer">${button('Cancel','close-dialog')}<button class="button primary" type="submit">${icon('upload')}Validate and import</button></div><p class="form-error" id="upload-error" role="alert"></p></form>`);}
async function startJob(path,body){
  const fingerprint=path+JSON.stringify(body);if(state.busy.has(fingerprint))throw new Error('This request is already being submitted.');state.busy.add(fingerprint);
  let key=state.jobKeys.get(fingerprint);if(!key){key=crypto.randomUUID();state.jobKeys.set(fingerprint,key);}
  try{const result=await api(path,{method:'POST',body,job:true,key});state.jobKeys.delete(fingerprint);state.jobId=result.job_id;if(Array.isArray(body.subsets)&&body.subsets.length){state.subset=body.subsets.length===1?body.subsets[0]:'ALL';localStorage.setItem('aeroguard-subset',state.subset);}closeDialog();toast(`Job ${result.job_id} queued. No duplicate execution is started for a repeated request.`);navigate('/pipeline');return result;}finally{state.busy.delete(fingerprint);}
}
async function jobDialog(id){openDialog('Pipeline execution','Loading recorded stages…','<div class="page-loading" style="min-height:180px"><div class="loader"></div></div>',{wide:true});try{const job=await api('/jobs/'+encodeURIComponent(id));if(!$('#dialog').open)return;openDialog('Pipeline execution',esc(job.id)+` · ${pretty(job.kind)} · ${job.configuration?.mode==='demo'?'Synthetic demonstration':'Historical benchmark'}`,`<div class="actions" style="margin-bottom:15px">${badge(job.status)}<span class="small muted">Started ${date(job.started_at||job.created_at)}</span></div>${job.error?`<p class="inline-error">${esc(job.error)}</p>`:''}<div id="dialog-job-stages">${jobStages(job)}</div>${['failed','interrupted'].includes(job.status)?`<div class="dialog-footer">${button('Retry safely','retry-job','refresh-cw','soft',`data-id="${esc(id)}"`)}</div>`:''}`,{wide:true});$('#dialog').dataset.jobId=id;$('#dialog').dataset.jobStatus=job.status;}catch(error){openDialog('Run unavailable','',`<p class="error-box">${esc(error.message)}</p>`);}}
async function modelDialog(id){openDialog('Model run details','Loading model artifacts and metrics…','<div class="page-loading" style="min-height:180px"><div class="loader"></div></div>',{wide:true});try{const r=await api('/models/'+encodeURIComponent(id));if(!$('#dialog').open)return;const files=r.artifacts||r.artifact_files||r.files||[],split=r.split||{};openDialog('Model run details',esc(r.run_id||id),`<div class="actions">${tag(r.subset||'Model')}${badge(r.training_status||'complete')}<a class="button small" href="/api/models/${encodeURIComponent(id)}/download">${icon('download')}Download immutable bundle</a></div><div class="divider"></div><div class="form-grid"><section><h3>Development evaluation</h3><pre class="json-block">${esc(JSON.stringify(r.validation_metrics||{},null,2))}</pre></section><section><h3>Official test evaluation</h3><pre class="json-block">${esc(JSON.stringify(r.evaluation?.metrics||r.evaluation||{status:'Not evaluated'},null,2))}</pre></section></div><details open><summary>Reproducible configuration</summary><pre class="json-block">${esc(JSON.stringify(r.configuration||{},null,2))}</pre></details><details><summary>Engine-disjoint split and calibration</summary><pre class="json-block">${esc(JSON.stringify({split,calibration:r.calibration},null,2))}</pre></details><details><summary>Artifact paths and integrity</summary><p class="mono">${esc(r.artifact_path||'')}</p><pre class="json-block">${esc(JSON.stringify(files.length?files:r.hashes||r.manifest||{},null,2))}</pre></details><details><summary>Full experiment record</summary><pre class="json-block">${esc(JSON.stringify(r,null,2))}</pre></details>`,{wide:true});}catch(error){openDialog('Model unavailable','',`<p class="error-box">${esc(error.message)}</p>`);}}
async function orderDialog(id){openDialog('Work order details','Loading saved evidence and audit history…','<div class="page-loading" style="min-height:180px"><div class="loader"></div></div>',{wide:true});try{const o=await api('/orders/'+encodeURIComponent(id)+'?'+modeQuery());if(!$('#dialog').open)return;const audit=o.audit||[],e=o.evidence||{};openDialog('Work order '+esc(o.id),`${esc(o.asset)} · Simulated local maintenance record`,`<div class="actions">${badge(o.priority)}${badge(o.status)}${o.status!=='resolved'?button('Manage order','manage-order','wrench','small soft',`data-id="${esc(o.id)}"`):''}<a class="button small" href="${enginePath(o.asset)}" data-nav>${icon('wind')}Engine details</a></div><div class="divider"></div><div class="form-grid"><section><h3>Maintenance evidence</h3><div class="key-values"><div><span>Engine / subset</span><strong>${esc(o.asset)}</strong></div><div><span>RUL at creation</span><strong>${num(o.predicted_rul??e.rul,1)} cycles</strong></div><div><span>Latest evidence RUL</span><strong>${num(o.current_rul??e.rul,1)} cycles</strong></div><div><span>Model replay</span><strong class="mono">${esc(o.bundle_id||o.namespace||'Not available')}</strong></div><div><span>Target cycle</span><strong>${num(o.target_cycle)}</strong></div><div><span>Owner</span><strong>${esc(o.owner||'Unassigned')}</strong></div><div><span>Created</span><strong>${date(o.created_at)}</strong></div><div><span>Revision</span><strong>${num(o.revision)}</strong></div></div><p class="small muted" style="margin-top:18px">${esc(o.reason||'Recorded triage evidence')}</p><p class="small muted">${esc(o.notes||'No resolution notes recorded.')}</p>${o.resolution?`<span class="tag green">${esc(pretty(o.resolution))}</span>`:''}</section><section><h3>Audit history</h3><div class="audit-list">${audit.length?audit.map(a=>`<div class="audit-item"><strong>${esc(pretty(a.action))}</strong><small>${date(a.created_at||a.timestamp)}</small><p>${esc(a.details?.notes||a.details?.owner||JSON.stringify(a.details||{}))}</p></div>`).join(''):'<p class="small muted">Creation and triggering evidence are attached to the order. No manual changes have been recorded.</p>'}</div></section></div><details><summary>Immutable triggering input snapshot</summary><pre class="json-block">${esc(JSON.stringify(e,null,2))}</pre></details>`,{wide:true});}catch(error){openDialog('Order unavailable','',`<p class="error-box">${esc(error.message)}</p>`);}}
async function manageOrder(id){try{const o=await api('/orders/'+encodeURIComponent(id)+'?'+modeQuery());if(o.status==='resolved')return toast('This order is resolved; its evidence remains immutable.');openDialog('Manage maintenance order',`${esc(o.id)} · ${esc(o.asset)}`,`<p class="dialog-copy">Assign a responsible owner, start the work, or record an explicit maintenance outcome. These actions update a simulated local record.</p><div class="stack"><div>${button('Assign owner','assign-dialog','user','soft',`data-id="${esc(id)}"`)}</div>${o.status!=='in_progress'?`<div>${button('Start work','start-order','wrench','',`data-id="${esc(id)}"`)}</div>`:''}<div>${button('Resolve with outcome','resolve-dialog','check-check','primary',`data-id="${esc(id)}"`)}</div></div>`);}catch(error){toast(error.message);}}
function assignDialog(id){openDialog('Assign a maintenance owner',esc(id),`<form id="assign-form" data-id="${esc(id)}"><label class="field">Technician or owner<input name="owner" maxlength="80" placeholder="Owner name or team" required></label><label class="field">Assignment notes<textarea name="notes" maxlength="1500" placeholder="Optional context for this simulated task"></textarea></label><div class="dialog-footer">${button('Cancel','close-dialog')}<button class="button primary" type="submit">${icon('user')}Assign owner</button></div><p class="form-error" id="assign-error" role="alert"></p></form>`);}
function resolveDialog(id){openDialog('Resolve a maintenance order',esc(id),`<form id="resolve-form" data-id="${esc(id)}"><p class="dialog-copy">Record an observed maintenance outcome. Resolving an order does not imply a physical repair, guaranteed failure prevention, or an external dispatch.</p><label class="field">Maintenance outcome<select name="resolution"><option value="preventive_service">Preventive service completed</option><option value="sensor_repair">Sensor repaired</option><option value="confirmed_failure">Failure confirmed</option><option value="no_fault_found">No fault found</option><option value="deferred">Deferred after engineering review</option></select></label><label class="field">Resolution notes<textarea name="notes" maxlength="1500" placeholder="Describe the maintenance or review outcome" required></textarea></label><label class="check-line"><input name="confirm" type="checkbox" required>I confirm this outcome should be recorded and the order resolved.</label><div class="dialog-footer">${button('Cancel','close-dialog')}<button class="button primary" type="submit">${icon('check-check')}Confirm resolution</button></div><p class="form-error" id="resolve-error" role="alert"></p></form>`);}
async function orderAction(id,payload){await api('/orders/'+encodeURIComponent(id)+'?'+modeQuery(),{method:'PATCH',body:payload});closeDialog();toast('Work-order update saved to the local audit history.');await render({loading:false});}

async function notifications(){const box=$('#notifications'),trigger=$('[data-action="notifications"]');if(!box.hidden){box.hidden=true;trigger.setAttribute('aria-expanded','false');return;}box.hidden=false;trigger.setAttribute('aria-expanded','true');box.innerHTML='<div class="popover-empty">Loading recorded alerts…</div>';try{const data=await api('/notifications?'+modeQuery());if(!$('#notifications'))return;$('#notifications').innerHTML=`<div class="popover-heading">Recent notifications ${button('Close','close-notifications','','small')}</div>${data.items?.length?data.items.slice(0,12).map(n=>`<a href="${n.asset?enginePath(n.asset):n.order_id?'/work-orders?order='+encodeURIComponent(n.order_id):'/pipeline'}" data-nav><strong>${esc(n.title||pretty(n.severity))}</strong><small>${esc(n.message||'Recorded pipeline event')}</small><small>${date(n.timestamp)}</small></a>`).join(''):'<div class="popover-empty">No recorded notifications.</div>'}`;}catch(error){box.innerHTML=`<div class="popover-empty">${esc(error.message)}</div>`;}}
let searchTimer,searchController;
async function globalSearch(value){const box=$('#search-results');if(!box)return;if(!value.trim()){box.hidden=true;return;}if(searchController)searchController.abort();searchController=new AbortController();box.hidden=false;box.innerHTML='<div class="popover-empty">Searching engines and orders…</div>';try{const result=await api('/search?'+modeQuery()+'&q='+encodeURIComponent(value),{signal:searchController.signal});if(!$('#search-results')||$('#global-search').value!==value)return;const engines=result.engines||[],orders=result.orders||[];box.innerHTML=(engines.length?'<div class="popover-heading">Engines</div>'+engines.slice(0,5).map(a=>`<a href="${enginePath(a.asset)}" data-nav><strong>Engine ${engineLabel(a)}</strong><small>${a.subset} · cycle ${num(a.cycle)} · ${num(a.rul,1)} remaining cycles</small></a>`).join(''):'')+(orders.length?'<div class="popover-heading">Work orders</div>'+orders.slice(0,5).map(o=>`<a href="/work-orders?order=${encodeURIComponent(o.id)}" data-nav><strong>${esc(o.id)}</strong><small>${esc(o.asset)} · ${esc(pretty(o.status))}</small></a>`).join(''):'')+(!engines.length&&!orders.length?'<div class="popover-empty">No matching engines or work orders.</div>':'');}catch(error){if(error.name!=='AbortError'&&$('#search-results'))box.innerHTML=`<div class="popover-empty">${esc(error.message)}</div>`;}}
function setMode(mode){state.mode=mode;localStorage.setItem('aeroguard-mode',mode);state.enginePage=0;state.orderPage=0;state.jobId=null;render();}
function toggleMenu(){const side=$('#sidebar');if(!side)return;const open=side.classList.toggle('open');$('[data-action="menu"]')?.setAttribute('aria-expanded',String(open));$('#mobile-backdrop')?.remove();if(open){const cover=document.createElement('div');cover.id='mobile-backdrop';cover.className='sidebar-backdrop';cover.dataset.action='menu';document.body.append(cover);}}

document.addEventListener('click',async event=>{
  const nav=event.target.closest('a[data-nav]');if(nav&&!event.metaKey&&!event.ctrlKey&&!event.shiftKey&&event.button===0){event.preventDefault();$('#mobile-backdrop')?.remove();navigate(nav.getAttribute('href'));return;}
  const engine=event.target.closest('[data-engine]');if(engine){navigate(enginePath(engine.dataset.engine));return;}
  const target=event.target.closest('[data-action]');if(!target||target.disabled)return;
  const action=target.dataset.action,id=target.dataset.id;
  try{
    if(action==='menu'){toggleMenu();return;}
    if(action==='close-dialog'){closeDialog();return;}
    if(action==='refresh'){await render();return;}
    if(action==='notifications'){await notifications();return;}
    if(action==='close-notifications'){$('#notifications').hidden=true;$('[data-action="notifications"]').setAttribute('aria-expanded','false');return;}
    if(action==='benchmark-mode'){setMode('benchmark');return;}
    if(action==='landing-demo'){state.mode='demo';localStorage.setItem('aeroguard-mode','demo');navigate('/dashboard');return;}
    if(action==='reset-filters'){state.engineSearch='';state.severity='ALL';state.cycleMin='';state.cycleMax='';state.enginePage=0;history.replaceState({},'',location.pathname);await render();return;}
    if(action==='engine-prev'||action==='engine-next'){state.enginePage=Math.max(0,state.enginePage+(action==='engine-next'?1:-1));$('#main').innerHTML=enginesPage(state.data);return;}
    if(action==='engine-tab'){state.detailTab=target.dataset.value;$('#main').innerHTML=engineDetailsPage(state.data);return;}
    if(action==='research-predict'){const input=$('#research-cycle');if(!input.reportValidity())return;target.disabled=true;const box=$('#research-live-output');box.textContent='Verifying saved neural weights and predicting from the observed prefix…';try{const result=await api('/research/runs/'+encodeURIComponent(id)+'/predict?engine_id='+target.dataset.researchEngine+'&cycle='+input.value);box.textContent=`Predicted RUL: ${num(result.predicted_rul,2)} cycles · cycle ${num(result.cycle)} · ${result.device} · inference probes verified.`;}catch(error){box.textContent=error.message;}finally{target.disabled=false;}return;}
    if(action==='train-dialog'){trainDialog();return;}
    if(action==='retrain'){trainDialog(target.dataset.subset);return;}
    if(action==='pipeline-dialog'){pipelineDialog();return;}
    if(action==='prepare-dialog'){pipelineDialog('prepare');return;}
    if(action==='upload-dialog'){uploadDialog();return;}
    if(action==='model-detail'){await modelDialog(id);return;}
    if(action==='job-detail'){await jobDialog(id);return;}
    if(action==='order-detail'){await orderDialog(id);return;}
    if(action==='manage-order'){await manageOrder(id);return;}
    if(action==='assign-dialog'){assignDialog(id);return;}
    if(action==='resolve-dialog'){resolveDialog(id);return;}
    if(action==='order-status'){state.orderStatus=target.dataset.value;state.orderPage=0;$('#main').innerHTML=ordersPage(state.data);return;}
    if(action==='order-prev'||action==='order-next'){state.orderPage=Math.max(0,state.orderPage+(action==='order-next'?1:-1));$('#orders-table').innerHTML=orderTable(state.data.items||[]);return;}
    if(action==='select-job'){state.jobId=id;await render({loading:false});return;}
    if(action==='preview-data'){state.previewSubset=target.dataset.subset;state.subset=target.dataset.subset;localStorage.setItem('aeroguard-subset',state.subset);await render({loading:false});return;}
    if(action==='settings-defaults'){const currentName=state.settings?.researcher_name;const reset=structuredClone(defaults);if(currentName)reset.researcher_name=currentName;$('#main').innerHTML=settingsPage(reset);toast('Default values loaded. Save settings to apply them.');return;}
    if(action==='download-schema'){const headers=['unit','cycle',...Array.from({length:3},(_,i)=>`setting_${i+1}`),...Array.from({length:21},(_,i)=>`sensor_${i+1}`)];const blob=new Blob([headers.join(',')+'\n'],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='cmapss_sensor_schema.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return;}
    if(action==='promote'||action==='rollback'){confirmDialog(action==='rollback'?'Restore a previously promoted model?':'Promote this model candidate?',action==='rollback'?'This explicitly restores a retained model version. The action and previous active version are recorded in promotion history.':'The backend checks this candidate against the active model using development metrics. A candidate outside the configured criteria will not be promoted.',async()=>{await api('/models/promote',{method:'POST',body:{run_id:id,rollback:action==='rollback'}});toast('Model promotion recorded.');await render({loading:false});});return;}
    target.disabled=true;
    if(action==='retry-job'){await startJob('/jobs/'+encodeURIComponent(id)+'/retry',{});return;}
    if(action==='ack-order'){await orderAction(id,{action:'acknowledge'});return;}
    if(action==='start-order'){await orderAction(id,{action:'start'});return;}
  }catch(error){toast(error.message);}finally{target.disabled=false;}
});
document.addEventListener('input',event=>{
  if(event.target.id==='global-search'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>globalSearch(event.target.value),300);}
  if(event.target.id==='order-search'){state.orderSearch=event.target.value;state.orderPage=0;const input=event.target,start=input.selectionStart;$('#orders-table').innerHTML=orderTable(state.data.items||[]);const next=$('#order-search');next.focus();next.setSelectionRange(start,start);}
});
document.addEventListener('change',async event=>{
  const el=event.target;
  try{
    if(el.id==='research-engine-select'){navigate('/models?research='+encodeURIComponent(el.dataset.run)+'&engine='+el.value);return;}
    if(el.id==='data-mode'){setMode(el.value);return;}
    if(el.id==='global-subset'||el.id==='mobile-subset'){$('#mobile-backdrop')?.remove();state.subset=el.value;localStorage.setItem('aeroguard-subset',state.subset);state.enginePage=0;state.orderPage=0;state.trendAsset=null;if(state.route==='/data'&&state.subset!=='ALL')state.previewSubset=state.subset;await render();return;}
    if(el.id==='trend-engine'){state.trendAsset=el.value;await loadTrend(state.data.assets||[]);return;}
    if(el.id==='history-limit'){state.detailLimit=Number(el.value);await render({loading:false});return;}
    if(el.id==='sensor-select'){state.selectedSensor=el.value;$('#main').innerHTML=engineDetailsPage(state.data);return;}
    if(el.id==='order-priority'){state.orderPriority=el.value;state.orderPage=0;$('#orders-table').innerHTML=orderTable(state.data.items||[]);return;}
    if(el.id==='preview-subset'){state.previewSubset=el.value;state.subset=el.value;localStorage.setItem('aeroguard-subset',state.subset);await render({loading:false});return;}
    if(el.id==='preview-partition'){state.previewPartition=el.value;await render({loading:false});return;}
    if(el.dataset.modelCompare){el.checked?state.comparison.add(el.dataset.modelCompare):state.comparison.delete(el.dataset.modelCompare);$('#comparison-panel').innerHTML=comparisonMarkup(state.data.runs||[]);return;}
  }catch(error){toast(error.message);}
});
document.addEventListener('submit',async event=>{
  const form=event.target;
  if(form.id==='research-import-form'){event.preventDefault();const file=$('#research-bundle').files[0];if(!file)return;if(file.size>32*1024*1024){toast('Research bundle must be at most 32 MB.');return;}const submit=$('button[type="submit"]',form);submit.disabled=true;try{const result=await api('/research/import',{method:'POST',body:new FormData(form)});toast(result.reused?'Verified existing research bundle.':'Training bundle imported and verified.');navigate('/models?research='+encodeURIComponent(result.run.run_id));}catch(error){toast(error.message);}finally{submit.disabled=false;}return;}
  if(form.id==='global-search-form'){event.preventDefault();const q=$('#global-search').value.trim();if(q){try{const matches=await api('/search?'+modeQuery()+'&q='+encodeURIComponent(q));if(!matches.engines?.length&&matches.orders?.length){navigate(matches.orders.length===1?'/work-orders?order='+encodeURIComponent(matches.orders[0].id):'/work-orders?q='+encodeURIComponent(q));}else navigate('/engines?q='+encodeURIComponent(q));}catch(error){toast(error.message);}}return;}
  if(form.id==='filters-form'){event.preventDefault();const values=new FormData(form),minimum=values.get('cycle_min'),maximum=values.get('cycle_max');if(minimum&&maximum&&Number(minimum)>Number(maximum)){toast('From cycle must not exceed To cycle.');return;}state.engineSearch=String(values.get('engine')).trim();state.severity=String(values.get('severity'));state.cycleMin=String(minimum);state.cycleMax=String(maximum);state.enginePage=0;await render({loading:false});return;}
  const forms=['train-form','pipeline-form','upload-form','settings-form','assign-form','resolve-form','confirm-form'];if(!forms.includes(form.id))return;
  event.preventDefault();const submit=$('button[type="submit"]',form),values=new FormData(form);submit.disabled=true;
  try{
    if(form.id==='train-form'){const payload={subsets:values.getAll('subsets'),promote:values.has('promote'),track_mlflow:values.has('track_mlflow')};for(const key of ['iterations','learning_rate','max_leaf_nodes','seed','split_seed','window','stride','cap','replay_cycles'])payload[key]=Number(values.get(key));if(!payload.subsets.length)throw new Error('Choose at least one dataset subset.');await startJob('/models/train',payload);}
    if(form.id==='pipeline-form'){const payload={mode:form.dataset.kind==='prepare'?'benchmark':state.mode,subsets:values.getAll('subsets'),cycles:Number(values.get('cycles'))};if(!payload.subsets.length)throw new Error('Choose at least one dataset subset.');await startJob(form.dataset.kind==='prepare'?'/data/prepare':'/pipeline/run',payload);}
    if(form.id==='upload-form'){const file=values.get('file');if(!file?.size)throw new Error('Choose a dataset file.');if(file.size>32*1024*1024)throw new Error('Upload a file smaller than 32 MB.');await api('/data/import',{method:'POST',body:values});closeDialog();toast('Dataset validated and saved. No training was started.');state.previewSubset=values.get('subset');if(state.route!=='/data')navigate('/data');else await render({loading:false});}
    if(form.id==='settings-form'){const payload={policy:{}};for(const [key,value]of values){if(key.startsWith('policy.'))payload.policy[key.slice(7)]=Number(value);else payload[key]=['workspace_name','researcher_name','default_subset'].includes(key)?String(value):Number(value);}state.settings=await api('/settings',{method:'PUT',body:payload});toast('Settings saved. Archived decisions remain unchanged.');await render({loading:false});}
    if(form.id==='assign-form')await orderAction(form.dataset.id,{action:'assign',owner:String(values.get('owner')).trim(),notes:String(values.get('notes')).trim()});
    if(form.id==='resolve-form')await orderAction(form.dataset.id,{action:'resolve',resolution:values.get('resolution'),notes:String(values.get('notes')).trim()});
    if(form.id==='confirm-form'){const action=state.pendingConfirm;if(action){await action();closeDialog();}}
  }catch(error){const id={'train-form':'train-error','pipeline-form':'pipeline-error','upload-form':'upload-error','settings-form':'settings-error','assign-form':'assign-error','resolve-form':'resolve-error','confirm-form':'confirm-error'}[form.id];if($('#'+id))$('#'+id).textContent=error.message;else toast(error.message);}finally{submit.disabled=false;}
});
document.addEventListener('keydown',event=>{
  const row=event.target.closest('[data-engine]');if(row&&event.target===row&&['Enter',' '].includes(event.key)){event.preventDefault();navigate(enginePath(row.dataset.engine));}
  if(event.key==='Escape'){if($('#search-results'))$('#search-results').hidden=true;if($('#notifications'))$('#notifications').hidden=true;if($('#sidebar')?.classList.contains('open'))toggleMenu();}
  if(event.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();const tabs=[...event.target.parentElement.querySelectorAll('[role="tab"]')],i=tabs.indexOf(event.target),next=tabs[(i+(event.key==='ArrowRight'?1:tabs.length-1))%tabs.length];next.click();document.querySelector(`[role="tab"][data-value="${next.dataset.value}"]`)?.focus();}
});
document.addEventListener('click',event=>{if(!event.target.closest('.top-search')&&$('#search-results'))$('#search-results').hidden=true;if(!event.target.closest('.notification-wrap')&&$('#notifications')){$('#notifications').hidden=true;$('[data-action="notifications"]')?.setAttribute('aria-expanded','false');}});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
$('#dialog').addEventListener('close',()=>{state.pendingConfirm=null;delete $('#dialog').dataset.jobId;});
window.addEventListener('popstate',()=>{state.enginePage=0;state.orderPage=0;render();});
setInterval(async()=>{
  if(document.hidden)return;
  try{
    const dialogJob=$('#dialog').dataset.jobId;if(dialogJob&&$('#dialog').open){if(!['queued','running'].includes($('#dialog').dataset.jobStatus))return;const job=await api('/jobs/'+encodeURIComponent(dialogJob));$('#dialog').dataset.jobStatus=job.status;if($('#dialog-job-stages'))$('#dialog-job-stages').innerHTML=jobStages(job);return;}
    if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;
    if(state.route==='/pipeline'&&state.data?.items?.some(j=>['running','queued'].includes(j.status))&&!$('#dialog').open){await render({loading:false});}
    else if(state.route==='/dashboard'&&state.data?.jobs?.some(j=>['running','queued'].includes(j.status))&&!$('#dialog').open){await render({loading:false});}
  }catch{/* The visible refresh action allows recovery without losing form input. */}
},3500);
installMLOps({api,state,render,startJob,openDialog,closeDialog,toast,button,esc,subsets});
render();
